export function workTitle(title?:string){const value=String(title||"").trim();return value||"未命名画廊"}
export function workTitleFont(){return "headline" as const}
export function workTitleLines(layout:"row"|"card"|"strip"="card"){return layout==="row"?3:2}
export function readingProgressLabel(page:number,total=0){const current=Math.max(1,Math.trunc(Number(page)||1)),pages=Math.max(0,Math.trunc(Number(total)||0));return pages>0?`阅读进度 · 第 ${current} 页 / ${pages}`:`阅读进度 · 第 ${current} 页`}
export function continueReadingTitle(page:number|null|undefined){return page?`继续阅读 · 第 ${page} 页`:"开始阅读"}
export function readerPageCaption(page:number){return `第 ${Math.max(1,Math.trunc(Number(page)||1))} 页`}
export function historyStatusLabel(){return "历史记录"}
export function localBookmarkStatusLabel(){return "本地书签"}
export function downloadPhaseLabel(status:string,failedCount=0){if(status==="completed")return "已完成";if(status==="downloading")return "正在下载";if(status==="queued")return "排队中";if(status==="failed"||failedCount>0)return "需要重试";if(status==="cancelled")return "已停止，可继续";return "已暂停，可继续"}
export function libraryDownloadNote(done:number,target:number,status:string,failedCount=0){return `下载 ${Math.max(0,Math.trunc(done))}/${Math.max(0,Math.trunc(target))} 页 · ${downloadPhaseLabel(status,failedCount)}`}
export function GalleryRow({item,note="",eager=false}:{item:GallerySummary;note?:string;eager?:boolean}){return <GlassSurface padding={10}><HStack spacing={12}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{width:82,height:112}} cornerRadius={9} eager={eager}/>:<Image systemName="photo" frame={{width:82,height:112}} foregroundStyle="secondaryLabel"/>}<VStack alignment="leading" spacing={7} frame={{maxWidth:"infinity"}}><Text font={workTitleFont()} fontWeight="semibold" lineLimit={workTitleLines("row")}>{workTitle(item.title)}</Text><GalleryBadges item={item}/><GalleryMetadata item={item}/>{note?<Text font="caption" foregroundStyle="systemBlue" lineLimit={2}>{note}</Text>:null}</VStack></HStack></GlassSurface>}
export function galleryIdentity(item:Pick<GallerySummary,"id"|"gid"|"token"|"url">){return item.id||[item.gid,item.token].filter(Boolean).join(":")||item.url||""}
export function galleryGridColumnCount(sizeClass:string|null|undefined){return sizeClass==="compact"?1:3}
export function selectGallery<T>(current:T|null,next:T|null){return next}
export function galleryOpenMode(_sizeClass:string|null|undefined){return "push" as const}
export function swipeBackShouldPop(startX:number,translationWidth:number,translationHeight=0,edge=24,distance=72){const dx=Number(translationWidth),dy=Number(translationHeight);return Number(startX)<=edge&&dx>=distance&&Math.abs(dx)>=Math.abs(dy)}
export function readerSwipeAction(dx:number,dy:number,zoomed:boolean,direction:ReaderPreferences["direction"]="ltr",distance=48):"previous"|"next"|null{if(zoomed)return null;const x=Number(dx),y=Number(dy);if(!Number.isFinite(x)||!Number.isFinite(y)||Math.abs(x)<distance||Math.abs(x)<=Math.abs(y))return null;const swipeLeft=x<0;return direction==="rtl"?(swipeLeft?"previous":"next"):(swipeLeft?"next":"previous")}
export function heartFillForSlot(slot:number,rating:number):"empty"|"half"|"full"{const value=Number(rating);if(!Number.isFinite(value)||value<=0)return"empty";if(value>=slot)return"full";return value>=slot-0.5?"half":"empty"}
export function pickHeartRating(slot:number,half:boolean){const n=Math.trunc(Number(slot));if(n<1||n>5)return 0;return half?n-0.5:n}
export function displayedHeartRating(userRating:number,average:number|null|undefined){if(Number(userRating)>0)return Number(userRating);const value=Number(average);return Number.isFinite(value)&&value>0?value:0}
export function nextHeartRating(slot:number,currentPick:number){const n=Math.trunc(Number(slot));if(n<1||n>5)return 0;return Number(currentPick)===n?n-0.5:n}
function HeartRatingPicker({rating,disabled=false,onPick}:{rating:number;disabled?:boolean;onPick:(slot:number)=>void}){return <HStack spacing={8}>{[1,2,3,4,5].map(slot=>{const fill=heartFillForSlot(slot,rating);return <Button key={slot} buttonStyle="plain" disabled={disabled} action={()=>onPick(slot)}><Image systemName={fill==="empty"?"heart":"heart.fill"} foregroundStyle={fill==="empty"?"secondaryLabel":"systemRed"} opacity={fill==="half"?0.55:1} frame={{width:36,height:32}}/></Button>})}</HStack>}
// Count mounted details, not visible screens: pushing a reader must keep the sidebar hidden.
let mountedGalleryDetails=0
const galleryDetailListeners=new Set<(count:number)=>void>()
export function mountGalleryDetail(){
  let mounted=true
  mountedGalleryDetails+=1
  galleryDetailListeners.forEach(listener=>listener(mountedGalleryDetails))
  return()=>{if(!mounted)return;mounted=false;mountedGalleryDetails-=1;galleryDetailListeners.forEach(listener=>listener(mountedGalleryDetails))}
}
export function subscribeGalleryDetailCount(listener:(count:number)=>void){galleryDetailListeners.add(listener);listener(mountedGalleryDetails);return()=>{galleryDetailListeners.delete(listener)}}
function openListedGallery(_sizeClass:string|null|undefined,item:GallerySummary,setSelected:(item:GallerySummary|null)=>void){setSelected(item)}
type ViewScope = { signal: AbortSignal; isCurrent: () => boolean }
function useViewScope(key: string): ViewScope {
  const generation = getAccountSessionGeneration()
  const current = useRef<{key: string; generation: number; controller: AbortController} | null>(null)
  if (!current.current || current.current.key !== key || current.current.generation !== generation) {
    current.current?.controller.abort()
    current.current = {key, generation, controller: new AbortController()}
  }
  const owner = current.current
  useEffect(() => () => owner.controller.abort(), [owner])
  return {signal: owner.controller.signal, isCurrent: () => current.current === owner && !owner.controller.signal.aborted && generation === getAccountSessionGeneration()}
}
// A native push owns one destination until its own dismissal. Rapid taps and old
// dismissal callbacks must not replace/clear another destination mid-transition.
function usePushDestination<T>(scope: ViewScope) {
  type Entry = {value: T; sequence: number}
  const [entry, setEntry] = useState<Entry | null>(null), owner = useRef<Entry | null>(null), sequence = useRef(0)
  useEffect(() => { owner.current = null; setEntry(null) }, [scope.signal])
  const select = (value: T | null) => {
    if (!scope.isCurrent()) return
    if (value === null) {
      if (owner.current !== entry) return
      owner.current = null; setEntry(null)
    } else if (!owner.current) {
      const next = {value, sequence: ++sequence.current}
      owner.current = next; setEntry(next)
    }
  }
  const navigationTicket = () => { const version = sequence.current; return () => scope.isCurrent() && !owner.current && sequence.current === version }
  return [entry?.value ?? null, select, entry?.sequence ?? 0, navigationTicket] as const
}
