export function glassGroupMixesInPlaceAndNavigation(items:Array<"inplace"|"navigate">){return items.includes("inplace")&&items.includes("navigate")}
async function saveSearchBookmark(state:GallerySearchState){const title=await prompt({title:"保存搜索书签",message:"只会保存在本机，保存后留在当前页。",defaultValue:searchBookmarkDefaultTitle(state),confirmLabel:"保存",cancelLabel:"取消"});if(title==null)return null;const name=title.trim()||searchBookmarkDefaultTitle(state);await saveSearch(state,name);return name}
function SearchComposer({initial,compact=false}:{initial:GallerySearchState;compact?:boolean}){const[state,setState]=useState(cloneSearchState(initial)),[input,setInput]=useState(initial.keyword),[suggestions,setSuggestions]=useState(searchLocalTagSuggestions(initial.keyword)),[translationStatus,setTranslationStatus]=useState(getTagTranslationStatus()),[notice,setNotice]=useState(""),[actionError,setActionError]=useState(""),[route,setRoute]=useState<{kind:string;state?:GallerySearchState}|null>(null),inputRef=useRef(initial.keyword),[searchHistory,setSearchHistory]=useState<string[]>([]),[searchFocused,setSearchFocused]=useState(false);useEffect(()=>{let cancelled=false;void loadSearchHistory().then(items=>{if(!cancelled)setSearchHistory(items)}).catch(()=>{});return()=>{cancelled=true}},[]);useEffect(()=>{let cancelled=false;void ensureTagTranslations().then(()=>{if(cancelled)return;setTranslationStatus(getTagTranslationStatus());setSuggestions(searchLocalTagSuggestions(inputRef.current))});return()=>{cancelled=true}},[]);const changeText=(value:string)=>{inputRef.current=value;setInput(value);setSuggestions(searchLocalTagSuggestions(value));setState(current=>composeGallerySearchState(current,value,current.selectedTags||[]))};const select=(value:{namespace:string;tag:string;translated:string})=>{const tag=createGallerySearchTag(value.namespace,value.tag,value.translated);if(!tag)return;inputRef.current="";setInput("");setSuggestions([]);setState(current=>selectGallerySearchTag(current,tag));};const remove=(tag:GallerySearchTag)=>setState(current=>removeGallerySearchTag(current,tag));const save=async()=>{setNotice("");setActionError("");try{const name=await saveSearchBookmark(state);if(name)setNotice(`已保存「${name}」。`)}catch(error){setActionError(error instanceof Error?error.message:"保存搜索失败。")}};const submit=()=>{if(!searchComposerCanSubmit(state))return;setSearchFocused(false);if(state.keyword.trim())void recordSearchHistory(state.keyword).then(setSearchHistory).catch(()=>setActionError("搜索历史保存失败，搜索仍可继续。"));setRoute({kind:"results",state:cloneSearchState(state)})};const repeatSearch=(term:string)=>{setSearchFocused(false);inputRef.current=term;setInput(term);const next=createHomeSearchState(term);setState(next);void recordSearchHistory(term).then(setSearchHistory).catch(()=>setActionError("搜索历史保存失败，搜索仍可继续。"));setRoute({kind:"results",state:next})};const visibleHistory=searchFocused?searchHistory.filter(term=>!input.trim()||term.toLocaleLowerCase().includes(input.trim().toLocaleLowerCase())):[];const open=(kind:"ai-search"|"ai-recommend"|"filter"|"bookmarks"|"tools")=>setRoute({kind,state:cloneSearchState(state)});return <VStack alignment="leading" spacing={8} frame={{maxWidth:"infinity"}} navigationDestination={{isPresented:Boolean(route),onChanged:(presented:boolean)=>{if(!presented)setRoute(null)},content:route?.kind==="results"&&route.state?<ResultsView initial={route.state}/>:route?.kind==="ai-search"?<AISearchFlow/>:route?.kind==="ai-recommend"?<AIRecommendationFlow/>:route?.kind==="tools"?<SearchScene initial={route.state}/>:route?.kind==="filter"?<HomeFilterEntry initial={route.state||state}/>:route?.kind==="bookmarks"?<QuickSearchScene/>:<VStack/>}}><HStack spacing={8} frame={{maxWidth:"infinity"}}><GlassSurface padding={compact?4:8}><HStack spacing={8}><Image systemName="magnifyingglass" foregroundStyle="secondaryLabel"/><TextField title="搜索画廊" value={input} onChanged={changeText} prompt="标题、作者或标签" submitLabel="search" keyboardType="webSearch" onSubmit={submit} onFocus={()=>{setSearchFocused(true);void loadSearchHistory().then(setSearchHistory).catch(()=>{})}} textFieldStyle="plain" frame={{maxWidth:"infinity",minHeight:44}}/>{compact?<><Button title="搜索" systemImage="magnifyingglass" labelStyle="iconOnly" buttonStyle="plain" frame={{minWidth:44,minHeight:44}} disabled={!searchComposerCanSubmit(state)} action={submit}/><Menu title="搜索工具" systemImage="slider.horizontal.3" labelStyle="iconOnly" frame={{minWidth:44,minHeight:44}}><Button title="AI 搜索" systemImage="sparkles" action={()=>open("ai-search")}/><Button title="高级筛选" systemImage="line.3.horizontal.decrease" action={()=>open("filter")}/><Button title="搜索书签" systemImage="bookmark" action={()=>open("bookmarks")}/><Button title="全部搜索工具" systemImage="magnifyingglass" action={()=>open("tools")}/></Menu></>:null}</HStack></GlassSurface>{!compact?<Button title="搜索" systemImage="magnifyingglass" buttonStyle="borderedProminent" disabled={!searchComposerCanSubmit(state)} action={submit}/>:null}</HStack>{visibleHistory.length?<VStack alignment="leading" spacing={4} frame={{maxWidth:"infinity"}}><Text font="caption" foregroundStyle="secondaryLabel">搜索历史 · 最近 {searchHistory.length} 条</Text><ScrollView frame={{height:Math.min(visibleHistory.length,5)*48}}><VStack alignment="leading" spacing={0} frame={{maxWidth:"infinity"}}>{visibleHistory.map(term=><Button key={term} buttonStyle="plain" action={()=>repeatSearch(term)} frame={{maxWidth:"infinity"}}><HStack spacing={10} padding={{horizontal:10}} frame={{maxWidth:"infinity",height:48,alignment:"leading"}}><Image systemName="clock.arrow.circlepath" foregroundStyle="secondaryLabel"/><Text lineLimit={1} frame={{maxWidth:"infinity",alignment:"leading"}}>{term}</Text><Image systemName="arrow.up.left" foregroundStyle="secondaryLabel"/></HStack></Button>)}</VStack></ScrollView></VStack>:null}{state.selectedTags.length?<ScrollView axes="horizontal"><HStack spacing={7}>{state.selectedTags.map(tag=><Button key={`${tag.namespace}:${tag.tag}`} title={`${tag.display} ×`} buttonStyle="bordered" action={()=>remove(tag)}/>)}</HStack></ScrollView>:null}{suggestions.length?<VStack alignment="leading" spacing={5}>{suggestions.slice(0,8).map(item=><Button key={`${item.namespace}:${item.tag}`} title={`${item.namespace}:${item.tag} / ${item.translated}`} action={()=>select(item)}/>)}</VStack>:null}{!compact?<><LazyVGrid columns={[{size:{type:"flexible" as const}},{size:{type:"flexible" as const}}]} alignment="leading" spacing={8}><GlassActionButton title="AI 搜索" systemImage="sparkles" compact action={()=>open("ai-search")}/><GlassActionButton title="AI 推荐" systemImage="wand.and.stars" compact action={()=>open("ai-recommend")}/></LazyVGrid><LazyVGrid columns={[{size:{type:"flexible" as const}},{size:{type:"flexible" as const}}]} alignment="leading" spacing={8}><GlassActionButton title="高级筛选" systemImage="line.3.horizontal.decrease.circle" compact action={()=>open("filter")}/><GlassActionButton title="已存书签" systemImage="bookmark" compact action={()=>open("bookmarks")}/></LazyVGrid><GlassActionButton title="保存搜索书签" systemImage="square.and.arrow.down" compact disabled={!state.rawQuery.trim()&&!state.selectedTags.length} action={()=>void save()}/></>:null}{actionError?<ErrorText message={actionError}/>:null}{notice?<Text font="caption" foregroundStyle="systemGreen">{notice}</Text>:null}{state.rawQuery?<Text font="caption" foregroundStyle="secondaryLabel">{state.rawQuery}</Text>:null}{!compact?<Text font="caption" foregroundStyle={translationStatus.fullDatabaseLoaded?"secondaryLabel":"systemOrange"}>{translationStatus.fullDatabaseLoaded?`完整标签库 ${translationStatus.count} 条 · ${translationStatus.source}`:translationStatus.error?`标签库加载失败：${translationStatus.error}`:"正在加载完整标签库…"}</Text>:null}</VStack>}

export function SearchScene({initial=createHomeSearchState()}:{initial?:GallerySearchState}={}){return <List navigationTitle="搜索" navigationBarTitleDisplayMode="large" background={<PageBackground/>}><Section><SearchComposer initial={initial}/></Section><Section footer={<Text>标签建议来自本地翻译库；已选标签使用 E-Hentai 精确标签语法。</Text>}><NavigationLink destination={<QuickSearchScene/>}><Text>已保存的快速搜索</Text></NavigationLink></Section></List>}

function FilterView({ initial, onApply, dismissAfterApply = true, navigationDestination }: {
  initial: GallerySearchState
  onApply: (state: GallerySearchState) => void
  dismissAfterApply?: boolean
  navigationDestination?: any
}) {
  const dismiss = Navigation.useDismiss()
  const [excludedCategoryMask, setExcludedCategoryMask] = useState(initial.excludedCategoryMask)
  const [quick, setQuick] = useState<QuickFilterKey>(initial.quickFilter)
  const [advanced, setAdvanced] = useState(initial.advanced)
  const apply = () => {
    onApply({ ...cloneSearchState(initial), excludedCategoryMask, quickFilter: quick, advanced })
    if (dismissAfterApply) dismiss()
  }
  return <List navigationTitle="搜索筛选" navigationBarTitleDisplayMode="inline" listStyle="insetGroup" navigationDestination={navigationDestination} toolbar={{topBarTrailing:<Button title="应用" action={apply}/>}}>
    <Section header={<Text textCase={null}>分类</Text>} footer={<Text>勾选的分类会显示在搜索结果中。</Text>}>{GALLERY_CATEGORIES.filter(item=>item.bit).map(item=>{const included=(excludedCategoryMask&item.bit)===0;return <Button key={item.key} buttonStyle="plain" action={()=>setExcludedCategoryMask(mask=>toggleExcludedCategory(mask,item.bit))}><HStack spacing={12} frame={{maxWidth:"infinity",minHeight:44,alignment:"leading"}}><Text frame={{maxWidth:"infinity",alignment:"leading"}}>{item.label}</Text>{included?<Image systemName="checkmark" foregroundStyle="accentColor"/>:null}</HStack></Button>})}{excludedCategoryMask?<Button title="全选分类" action={()=>setExcludedCategoryMask(0)}/>:null}</Section>
    <Section header={<Text textCase={null}>语言与常用筛选</Text>} footer={<Text>只能选择一项；“不限语言”显示所有语言。</Text>}>{QUICK_FILTERS.map(item=><Button key={item.key} buttonStyle="plain" action={()=>setQuick(item.key)}><HStack spacing={12} frame={{maxWidth:"infinity",minHeight:44,alignment:"leading"}}><Text frame={{maxWidth:"infinity",alignment:"leading"}}>{item.label}</Text>{quick===item.key?<Image systemName="checkmark" foregroundStyle="accentColor"/>:null}</HStack></Button>)}</Section>
    <Section header={<Text textCase={null}>高级搜索</Text>}><Toggle title="启用高级搜索" value={advanced.enabled} onChanged={enabled=>setAdvanced(current=>({...current,enabled}))}/>{advanced.enabled ? <VStack alignment="leading" spacing={8}><Button title={`${advanced.searchName ? "✓" : "○"} 搜索画廊名称`} action={() => setAdvanced({ ...advanced, searchName: !advanced.searchName })} /><Button title={`${advanced.searchTags ? "✓" : "○"} 搜索画廊标签`} action={() => setAdvanced({ ...advanced, searchTags: !advanced.searchTags })} /><Button title={`${advanced.searchDescription ? "✓" : "○"} 搜索画廊描述`} action={() => setAdvanced({ ...advanced, searchDescription: !advanced.searchDescription })} /><VStack alignment="leading" spacing={8}><Text font="caption">最低评分</Text><LazyVGrid columns={[{size:{type:"adaptive",min:64,max:96}}]} alignment="leading" spacing={8}>{(["","2","3","4","5"] as const).map(value=><Button key={value||"any"} title={value?`${value}+`:"不限"} buttonStyle={advanced.minimumRating===value?"borderedProminent":"bordered"} action={()=>setAdvanced({...advanced,minimumRating:value})}/>)}</LazyVGrid></VStack><HStack spacing={8}><TextField title="最少页数" value={advanced.pageFrom} onChanged={pageFrom=>setAdvanced({...advanced,pageFrom:pageFrom.replace(/\D/g,"")})} prompt="最少" keyboardType="numberPad"/><TextField title="最多页数" value={advanced.pageTo} onChanged={pageTo=>setAdvanced({...advanced,pageTo:pageTo.replace(/\D/g,"")})} prompt="最多" keyboardType="numberPad"/></HStack><Button title={`${advanced.searchTorrents?"✓":"○"} 仅含种子`} action={()=>setAdvanced({...advanced,searchTorrents:!advanced.searchTorrents})}/><Button title={`${advanced.searchTorrentFilenames?"✓":"○"} 搜索种子文件名`} action={()=>setAdvanced({...advanced,searchTorrentFilenames:!advanced.searchTorrentFilenames})}/><Button title={`${advanced.searchLowPowerTags?"✓":"○"} 搜索低权重标签`} action={()=>setAdvanced({...advanced,searchLowPowerTags:!advanced.searchLowPowerTags})}/><Button title={`${advanced.searchDownvotedTags?"✓":"○"} 搜索被否决标签`} action={()=>setAdvanced({...advanced,searchDownvotedTags:!advanced.searchDownvotedTags})}/><Button title={`${advanced.disableLanguageFilter?"✓":"○"} 禁用默认语言过滤`} action={()=>setAdvanced({...advanced,disableLanguageFilter:!advanced.disableLanguageFilter})}/><Button title={`${advanced.disableUploaderFilter?"✓":"○"} 禁用默认上传者过滤`} action={()=>setAdvanced({...advanced,disableUploaderFilter:!advanced.disableUploaderFilter})}/><Button title={`${advanced.disableTagFilter?"✓":"○"} 禁用默认标签过滤`} action={()=>setAdvanced({...advanced,disableTagFilter:!advanced.disableTagFilter})}/><Button title={`${advanced.showExpunged?"✓":"○"} 显示已删除`} action={()=>setAdvanced({...advanced,showExpunged:!advanced.showExpunged})}/></VStack> : null}</Section>
  </List>
}

function ResultsView({ initial }: { initial: GallerySearchState }) {
  const [state, setState] = useState(cloneSearchState(initial))
  const [queryDraft, setQueryDraft] = useState(initial.keyword)
  const [panel, setPanel] = useState<"filter"|"bookmarks"|null>(null)
  const [saveNotice, setSaveNotice] = useState("")
  const [saveError, setSaveError] = useState("")
  const [items, setItems] = useState<GallerySummary[]>([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [resultCount, setResultCount] = useState("")
  const [prev, setPrev] = useState("")
  const [next, setNext] = useState("")
  const requestEpoch = useRef(0),requestController=useRef<AbortController|null>(null)
  const load = async (direct?: string, nextState: GallerySearchState = state) => {
    requestController.current?.abort();const controller=new AbortController();requestController.current=controller
    const epoch = ++requestEpoch.current, generation=getAccountSessionGeneration()
    setLoading(true);setError("");setItems([]);setResultCount("");setPrev("");setNext("")
    const url = direct ? routeUrlForSite(direct) : buildGallerySearchUrl(getBaseUrl(), nextState)
    try {
      const page = await searchGalleries("", url, controller.signal)
      if (epoch !== requestEpoch.current || generation!==getAccountSessionGeneration()) return
      setItems(page.items); setResultCount(page.resultCount); setPrev(page.prevHref); setNext(page.nextHref)
      await reportSafe({ stage: "gallery-search-filter", ok: true, request: { url: page.url }, notes: `items=${page.items.length}; excludedMask=${nextState.excludedCategoryMask}; tagPresent=${nextState.mode === "tag"}` })
    } catch (caught) {
      if (epoch !== requestEpoch.current || generation!==getAccountSessionGeneration()) return
      setError(caught instanceof Error ? caught.message : String(caught)); setItems([]);setResultCount("");setPrev("");setNext("")
    } finally {
      if (epoch === requestEpoch.current && requestController.current===controller) setLoading(false)
    }
  }
  useEffect(() => { void load(undefined, initial); return()=>{requestEpoch.current+=1;requestController.current?.abort()} }, [getAccountSessionGeneration()])
  const apply = (value: GallerySearchState) => { setState(value);setQueryDraft(value.keyword); setPrev(""); setNext(""); void load(undefined, value) }
  const searchAgain = () => {const value=composeGallerySearchState({...state,mode:"normal" as const,sourceUrl:""},queryDraft,state.selectedTags);if(!searchComposerCanSubmit(value))return;apply(value);if(value.keyword)void recordSearchHistory(value.keyword).catch(()=>setSaveError("搜索历史保存失败，搜索仍可继续。"))}
  return <List navigationTitle="搜索结果" navigationBarTitleDisplayMode="inline" overlay={loading ? <ProgressView title="正在搜索…" progressViewStyle="circular" /> : undefined} listStyle="insetGroup" listSectionSpacing="compact" navigationDestination={{isPresented:Boolean(panel),onChanged:(presented:boolean)=>{if(!presented)setPanel(null)},content:panel==="filter"?<FilterView initial={state} onApply={apply}/>:panel==="bookmarks"?<QuickSearchScene/>:<VStack/>}}>
    <Section footer={<Text>{categoryExclusionSummary(state.excludedCategoryMask)} · {getQuickFilter(state.quickFilter).label}</Text>}><VStack alignment="leading" spacing={10} frame={{maxWidth:"infinity",alignment:"leading"}}><HStack alignment="top" spacing={12} frame={{maxWidth:"infinity",alignment:"leading"}}><VStack alignment="leading" spacing={4} frame={{maxWidth:"infinity",alignment:"leading"}}><HStack alignment="center" spacing={8} frame={{maxWidth:"infinity",alignment:"leading"}}><TextField title="搜索词" value={queryDraft} onChanged={setQueryDraft} prompt="修改搜索词" submitLabel="search" keyboardType="webSearch" onSubmit={searchAgain} textFieldStyle="plain" frame={{maxWidth:"infinity",minHeight:44}}/><Button title="搜索" systemImage="magnifyingglass" buttonStyle="borderedProminent" disabled={!queryDraft.trim()&&!state.selectedTags.length} action={searchAgain}/></HStack><Text font="subheadline" foregroundStyle="secondaryLabel">{resultCount ? `${resultCount} 个结果` : loading ? "正在搜索…" : `${items.length} 个结果`}</Text></VStack><Button title="筛选" systemImage="line.3.horizontal.decrease.circle" buttonStyle="bordered" action={()=>setPanel("filter")}/></HStack><LazyVGrid columns={[{size:{type:"flexible" as const}},{size:{type:"flexible" as const}}]} alignment="leading" spacing={8}><GlassActionButton title="保存搜索书签" systemImage="square.and.arrow.down" compact disabled={!state.rawQuery.trim()&&!state.selectedTags.length} action={()=>{setSaveNotice("");setSaveError("");void saveSearchBookmark(state).then(name=>{if(name)setSaveNotice(`已保存「${name}」。`)}).catch(error=>setSaveError(error instanceof Error?error.message:"保存搜索失败。"))}}/><GlassActionButton title="已存书签" systemImage="bookmark" compact action={()=>setPanel("bookmarks")}/></LazyVGrid>{saveNotice?<Text font="caption" foregroundStyle="systemGreen">{saveNotice}</Text>:null}{saveError?<ErrorText message={saveError}/>:null}{error?<ErrorText message={error}/>:null}</VStack></Section>
    <Section header={<Text textCase={null}>{items.length ? `本页 ${items.length} 条` : "搜索结果"}</Text>}><GalleryGrid items={items}/>{!loading && !error && items.length === 0 ? <EmptyState message="没有找到匹配的画廊。可调整搜索词或筛选条件后重试。" systemImage="magnifyingglass"/> : null}{error ? <Button title="重试搜索" buttonStyle="bordered" action={() => { void load() }} /> : null}</Section>
    {prev || next ? <Section footer={<Text>浏览更多结果</Text>}><HStack><Button title="上一页" systemImage="chevron.left" buttonStyle="bordered" disabled={!prev || loading} action={() => { if (prev) void load(prev) }} /><Spacer /><Button title="下一页" systemImage="chevron.right" buttonStyle="bordered" disabled={!next || loading} action={() => { if (next) void load(next) }} /></HStack></Section> : null}
  </List>
}

export function ImageSearchScene(){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(false),[error,setError]=useState(""),epoch=useRef(0);useEffect(()=>()=>{epoch.current+=1},[]);const run=async(coversOnly=false)=>{if(loading)return;const current=++epoch.current;setLoading(true);setError("");try{const picked=await Photos.pickPhotos(1),data=picked[0]?Data.fromJPEG(picked[0],.9):null;if(!data)throw new Error("无法读取所选图片。");const page=await imageSearch(data,{similar:true,coversOnly,showExpunged:true});if(current===epoch.current)setItems(page.items)}catch(e){if(current===epoch.current)setError(e instanceof Error?e.message:"图片搜索失败")}finally{if(current===epoch.current)setLoading(false)}};return <List navigationTitle="图片搜索" overlay={loading?<ProgressView title="正在上传并搜索…" progressViewStyle="circular"/>:undefined}><Section><Text font="caption" foregroundStyle="secondaryLabel">从照片中选择一张图片，使用 E-Hentai 图片搜索协议。图片仅发送到当前 E/Ex 搜索服务。</Text><HStack><Button title="相似图片搜索" buttonStyle="borderedProminent" disabled={loading} action={()=>void run(false)}/><Button title="仅搜索封面" buttonStyle="bordered" disabled={loading} action={()=>void run(true)}/></HStack>{error?<ErrorText message={error}/>:null}</Section><Section header={<Text textCase={null}>搜索结果 · {items.length}</Text>}><GalleryGrid items={items}/>{!loading&&!error&&!items.length?<EmptyState message="选择图片后，结果会复用现有画廊列表和详情流程。"/>:null}</Section></List>}
function CoverSearchScene({coverUrl,referer}:{coverUrl:string;referer:string}){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{let cancelled=false;void cachedImagePath(coverUrl,"detail-cover",detailCoverRequestOptions(coverUrl,referer)).then(path=>imageSearch(path,{similar:true,coversOnly:true,showExpunged:true})).then(page=>{if(!cancelled)setItems(page.items)}).catch(e=>{if(!cancelled)setError(e instanceof Error?e.message:"封面搜索失败")}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[coverUrl,referer]);return <List navigationTitle="搜索封面" overlay={loading?<ProgressView title="正在搜索封面…" progressViewStyle="circular"/>:undefined}><Section>{error?<ErrorText message={error}/>:null}<GalleryGrid items={items}/>{!loading&&!error&&!items.length?<EmptyState message="没有找到相似封面。"/>:null}</Section></List>}
function HomeFilterEntry({ initial }: { initial: GallerySearchState }) {
  const [result, setResult] = useState<GallerySearchState | null>(null)
  return <FilterView initial={initial} onApply={setResult} dismissAfterApply={false} navigationDestination={{isPresented:Boolean(result),onChanged:(presented:boolean)=>{if(!presented)setResult(null)},content:result?<ResultsView key={`${result.rawQuery}|${result.excludedCategoryMask}|${result.quickFilter}`} initial={result}/>:<VStack/>}} />
}

function AccountSection({ account, onAccountContextChanged }: { account: ReturnType<typeof getAccountStatus>; onAccountContextChanged: (status: ReturnType<typeof getAccountStatus>) => void }) {
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState("")
  const [notice, setNotice] = useState("")
  const [profiles, setProfiles] = useState(()=>listAccountProfiles())
  const updateContext = (status: ReturnType<typeof getAccountStatus>) => { onAccountContextChanged(status); setProfiles(listAccountProfiles()) }
  const run = async (action: "manual" | "safari" | "ex-sync" | "import" | "refresh" | "logout" | "e" | "ex") => {
    if (busy) return
    setBusy(true); setError(""); setNotice("")
    try {
      if (action === "manual") {
        const text=String(await Pasteboard.getString()||"").trim();if(!text)throw new Error("剪贴板中没有文本。请先复制三行 Cookie；如系统询问粘贴权限请选择允许。")
        const summary=manualCookieSummary(text);if(!summary.memberIdPresent||!summary.passHashPresent)throw new Error("剪贴板未同时识别到 ipb_member_id 和 ipb_pass_hash；不会保存任何内容。")
        const targetName=summary.target==="ex"?"ExHentai":"E-Hentai",approved=await confirm({title:`从剪贴板导入 ${targetName}？`,message:`已识别：member id ✓ · pass hash ✓ · igneous ${summary.igneousStructurallyValid?"✓":"无"}。不会显示、记录或上传 Cookie 值；确认后执行真实登录验证。`,confirmLabel:"验证并保存",cancelLabel:"取消"});if(!approved)return
        const result=await saveAndValidateManualCookie(text),status=result.status;updateContext(status);setNotice(result.target==="ex"?"已从剪贴板识别 igneous，并验证、切换到 ExHentai。":"剪贴板未包含 igneous，已按 E-Hentai 登录验证。")
      } else if (action === "safari") {
        await openSafariLogin();setNotice("已打开 Safari。登录后点击页面左下角 Cookie 助手，或在 Scripting 扩展菜单选择“获取 EH Cookie 并写入”，再返回此处导入。")
      } else if (action === "ex-sync") {
        await openSafariExSync();setNotice("已打开真实 ExHentai。确认页面可访问后点击 Cookie 助手，再返回此处导入；会合并真实 E/Ex Cookie，不会跨域复制。")
      } else if (action === "import") {
        const status=await importAndValidateBrowserCookies();updateContext(status);setNotice(status.exAvailable?"已导入并验证 E-Hentai / ExHentai 登录。":"已验证 E-Hentai 登录；当前账户暂不可使用 ExHentai。")
      } else if (action === "refresh") updateContext(await refreshAccountStatus())
      else if (action === "logout") { try { await signOut() } finally { updateContext(getAccountStatus()) } }
      else { setActiveSite(action); updateContext(getAccountStatus()) }
    } catch (caught) { setError(caught instanceof Error ? caught.message : String(caught)) }
    finally { setBusy(false) }
  }
  return <>
    <Section header={<Text textCase={null}>登录状态</Text>}><VStack alignment="leading" spacing={7}>
      <Text font="headline">{account.loggedIn ? account.eHentaiReachable&&account.exAvailable?"E-Hentai / ExHentai 已登录":account.exAvailable?"ExHentai 已登录":"E-Hentai 已登录":"游客模式"}</Text>
      <Text font="caption" foregroundStyle="secondaryLabel">E-Hentai：{account.eHentaiReachable===true?"可用":account.eHentaiReachable===false?"验证失败":"待检测"} · ExHentai：{account.exAvailable===true?"可用":account.exAvailable===false?"不可用":"待检测"}</Text>
      <Text font="caption" foregroundStyle="secondaryLabel">Cookie 仅保存在本机 Keychain，不会写入日志或仓库。</Text>
    </VStack></Section>
    <Section header={<Text textCase={null}>已保存账号</Text>} footer={<Text>点账号即可切换。导入另一个账号的 Cookie 会加入列表；最多保存 8 个。</Text>}>{profiles.length?profiles.map(item=><Button key={item.id} buttonStyle="plain" disabled={busy||item.current} action={()=>{if(item.current)return;void (async()=>{if(busy)return;setBusy(true);setError("");setNotice("");try{updateContext(switchAccountProfile(item.id));setNotice("已切换账号。")}catch(caught){setError(caught instanceof Error?caught.message:String(caught))}finally{setBusy(false)}})()}}><HStack spacing={10} frame={{maxWidth:"infinity"}}><Image systemName="person.crop.circle" foregroundStyle="accentColor"/><VStack alignment="leading" spacing={2} frame={{maxWidth:"infinity",alignment:"leading"}}><Text>{item.label}</Text><Text font="caption" foregroundStyle="secondaryLabel">{item.site==="ex"?"ExHentai":"E-Hentai"}</Text></VStack>{item.current?<Image systemName="checkmark" foregroundStyle="accentColor"/>:null}</HStack></Button>):<Text font="caption" foregroundStyle="secondaryLabel">登录成功后会自动加入列表。</Text>}</Section>
    {profiles.length?<Section header={<Text textCase={null}>删除账号</Text>} footer={<Text>删除当前账号会同时退出当前会话；只删除本机登录，不影响网站账号。</Text>}>{profiles.map(item=><Button key={`delete-${item.id}`} title={`${item.current?"删除当前账号并退出":"删除"} · ${item.label}`} role="destructive" disabled={busy} action={()=>{void (async()=>{if(busy)return;if(!await confirm({title:item.current?"删除当前账号并退出？":"删除这个账号？",message:item.current?"将删除本机保存的当前登录并进入游客模式；不影响网站账号。":"只删除本机保存的登录，不影响网站账号。",confirmLabel:"删除",cancelLabel:"取消"}))return;setBusy(true);setError("");setNotice("");try{const remaining=removeAccountProfile(item.id);if(remaining.some(profile=>profile.id===item.id||profile.memberId===item.id))throw new Error("账号仍在本机列表中，请重试。");updateContext(getAccountStatus());setNotice(item.current?"已删除当前账号并退出。":"已删除账号。")}catch(caught){setError(caught instanceof Error?caught.message:String(caught))}finally{setBusy(false)}})()}}/>)}</Section>:null}
    <Section header={<Text textCase={null}>登录</Text>} footer={<Text>在 Safari 登录并运行 Cookie 助手后，返回这里导入并验证。</Text>}><Button title="在 Safari 登录" systemImage="safari" disabled={busy} action={() => { void run("safari") }} /><Button title="同步里站登录" systemImage="arrow.triangle.2.circlepath" disabled={busy || !account.loggedIn} action={() => { void run("ex-sync") }} /><Button title="导入并验证登录状态" systemImage="checkmark.shield" buttonStyle="borderedProminent" disabled={busy} action={() => { void run("import") }} />{busy ? <ProgressView progressViewStyle="circular" /> : null}{notice?<Text font="caption" foregroundStyle="systemGreen">{notice}</Text>:null}{error?<ErrorText message={error}/>:null}</Section>
    {account.loggedIn?<Section header={<Text textCase={null}>站点</Text>} footer={<Text>{account.exAvailable!==true?"ExHentai 尚无可验证的真实 Ex 域登录会话，请先同步里站登录。":"当前账号可在两个站点之间切换。"}</Text>}><Button buttonStyle="plain" disabled={busy||account.site==="e"||account.eHentaiReachable!==true} action={()=>{void run("e")}}><HStack frame={{maxWidth:"infinity"}}><Text frame={{maxWidth:"infinity",alignment:"leading"}}>E-Hentai</Text>{account.site==="e"?<Image systemName="checkmark" foregroundStyle="accentColor"/>:null}</HStack></Button><Button buttonStyle="plain" disabled={busy||account.site==="ex"||account.exAvailable!==true} action={()=>{void run("ex")}}><HStack frame={{maxWidth:"infinity"}}><Text frame={{maxWidth:"infinity",alignment:"leading"}}>ExHentai{account.exAvailable!==true?" · 未验证":""}</Text>{account.site==="ex"?<Image systemName="checkmark" foregroundStyle="accentColor"/>:null}</HStack></Button></Section>:null}
    <Section header={<Text textCase={null}>高级账户操作</Text>} footer={<Text>Cookie 值不会显示、记录或上传；导入前会再次确认。</Text>}><Button title="从剪贴板导入 Cookie" systemImage="doc.on.clipboard" disabled={busy} action={() => { void run("manual") }} /><Button title="刷新登录状态" systemImage="arrow.clockwise" disabled={busy || !account.loggedIn} action={() => { void run("refresh") }} />{account.loggedIn?<Button title="退出当前账号" role="destructive" disabled={busy} action={() => { void run("logout") }} />:null}</Section>
  </>
}

function AccountOverviewEntry({account}:{account:ReturnType<typeof getAccountStatus>}){const generation=getAccountSessionGeneration(),[data,setData]=useState<Awaited<ReturnType<typeof loadAccountOverview>>|null>(null),[loading,setLoading]=useState(false),[unavailable,setUnavailable]=useState(""),[info,setInfo]=useState(""),epoch=useRef(0);const load=async()=>{const current=++epoch.current;if(!account.loggedIn){setData(null);setUnavailable("");setInfo("登录后可查看账户概览。");return}setLoading(true);setUnavailable("");setInfo("");try{const value=await loadAccountOverview();if(current!==epoch.current)return;setData(value)}catch(caught){if(current!==epoch.current)return;setData(null);const message=caught instanceof Error?caught.message:"";setUnavailable(message==="账户概览需要登录。"?message:accountOverviewUnavailableMessage())}finally{if(current===epoch.current)setLoading(false)}};useEffect(()=>{void load();return()=>{epoch.current+=1}},[account.loggedIn,account.site,generation]);return <Section header={<Text textCase={null}>账户信息</Text>} footer={unavailable?<Text>{unavailable}</Text>:undefined}><VStack alignment="leading" spacing={7}><HStack><Text font="headline">账户概览</Text><Spacer/><Button title="刷新" disabled={loading||!account.loggedIn} action={()=>void load()}/></HStack>{loading?<ProgressView progressViewStyle="circular"/>:null}{data?.imageLimitCurrent&&data.imageLimitMax?<Text>图片限额：{data.imageLimitCurrent} / {data.imageLimitMax}</Text>:null}{data?.resetCost?<Text font="caption" foregroundStyle="secondaryLabel">重置成本：{data.resetCost}</Text>:null}{data?.values.map(item=><Text key={item.label} font="caption" foregroundStyle="secondaryLabel">{item.label}：{item.value}</Text>)}{data&&!data.imageLimitCurrent&&!data.values.length?<Text font="caption" foregroundStyle="secondaryLabel">当前页面未提供可稳定显示的账户数据。</Text>:null}{info?<Text font="caption" foregroundStyle="secondaryLabel">{info}</Text>:null}</VStack></Section>}

export function imageDiagnosticSnapshot(){return{build:IMAGE_DIAGNOSTIC_BUILD,active:activeImageTasks,queued:pendingImageTasks.length,limit:MAX_IMAGE_REQUESTS,...imageDiagnostics.snapshot()}}
const imagePhaseLabels:Record<string,string>={queued:"排队",started:"已启动",mkdir:"创建缓存目录", "cache-check":"检查缓存",fetch:"等待网络响应",body:"读取响应体",validate:"检查图片格式",write:"写入缓存",report:"结束记录"}
export function ImageDiagnosticsScene(){
  const [snapshot,setSnapshot]=useState(imageDiagnosticSnapshot),[message,setMessage]=useState("")
  const refresh=()=>{setSnapshot(imageDiagnosticSnapshot());setMessage("")}
  const seconds=(ms:number)=>`${(ms/1000).toFixed(1)} 秒`
  const row=(item:typeof snapshot.pending[number])=><VStack key={String(item.id)} alignment="leading" spacing={4}><Text font="subheadline">#{item.id} · {item.stage} · {item.host}</Text><Text>阶段：{imagePhaseLabels[item.phase]||item.phase} · {seconds(item.phaseMs)}</Text><Text font="caption">总计 {seconds(item.elapsedMs)} · 排队 {seconds(item.queueMs)} · {item.outcome||"尚未结束"}{item.failurePhase?` · 失败位置：${imagePhaseLabels[item.failurePhase]}`:""}</Text><Text font="caption">HTTP {item.status||"未返回"} · {item.mime} · {item.bytes} 字节{item.retry?" · 重试":""}{item.cacheHit?" · 磁盘命中":""}{item.cacheError?" · 缓存检查异常":""}</Text>{item.timeoutWaitMs!==null?<Text font="caption" foregroundStyle="systemOrange">已触发超时 · 之后 {seconds(item.timeoutWaitMs)}{item.outcome?" 后结束":"仍未结束"}</Text>:null}{item.cancelWaitMs!==null?<Text font="caption">已请求取消 · 之后 {seconds(item.cancelWaitMs)}{item.outcome?" 后结束":"仍未结束"}</Text>:null}</VStack>
  return <List onAppear={refresh} navigationTitle="图片加载诊断" navigationBarTitleDisplayMode="inline"><Section><Text font="headline">{snapshot.build}</Text><Text>占用 {snapshot.active} / {snapshot.limit} · 排队 {snapshot.queued}</Text><Text font="caption">快照时间：{new Date(snapshot.capturedAt).toLocaleTimeString()} · 任务累计 {snapshot.total}</Text><Text font="caption">内存命中 {snapshot.memoryHits} · 共享请求 {snapshot.sharedHits} · 诊断超额未记录 {snapshot.dropped}</Text><Button title="刷新快照" action={refresh}/><Button title="复制脱敏诊断" action={()=>{void Pasteboard.setString(JSON.stringify(snapshot,null,2)).then(()=>setMessage("已复制，请返回聊天粘贴发送。")).catch(()=>setMessage("复制失败，请截图本页。"))}}/>{message?<Text>{message}</Text>:null}</Section><Section header={<Text textCase={null}>仍未结束的任务（前 24 条）</Text>}>{snapshot.pending.slice().sort((a,b)=>(a.started===null?1:0)-(b.started===null?1:0)||a.id-b.id).slice(0,24).map(row)}{!snapshot.pending.length?<Text>没有未结束任务。</Text>:null}</Section><Section header={<Text textCase={null}>最近结束（前 16 条）</Text>}>{snapshot.recent.slice(0,16).map(row)}</Section><Section><Text font="caption">D1 只观测，不清缓存、不取消任务、不改变并发。本页显示本次运行记录，另会自动保存有限脱敏快照到本机 App Group；不会上传。复制包含最多 512 条未结束及最近 80 条结束记录，无 Cookie、账号、画廊标题、路径或完整 URL。进入设置可能触发旧页面取消，历史记录仍保留它结束前的阶段。请不要在复现后重启脚本。</Text></Section></List>
}
function BuildMarker(){const[marker,setMarker]=useState("1.0.0-rc · 未同步");useEffect(()=>{let cancelled=false;void fileManager.readAsString(`${Script.directory}/sync-manifest.json`).then((text:string)=>{const value=JSON.parse(text),commit=String(value?.commit||"");if(!cancelled&&value?.version&&value?.branch&&commit)setMarker(`${value.version} · ${commit.slice(0,7)} · ${value.branch}`)}).catch(()=>{});return()=>{cancelled=true}},[]);return <Section header={<Text textCase={null}>开发与诊断</Text>} footer={<Text>仅用于问题排查；诊断不会显示 Cookie、账号值或完整私密 URL。</Text>}><NavigationLink destination={<ImageDiagnosticsScene/>}><Label title="图片加载诊断" systemImage="waveform.path.ecg"/></NavigationLink><Text font="caption" foregroundStyle="secondaryLabel">{IMAGE_DIAGNOSTIC_BUILD}</Text><Text font="caption2" foregroundStyle="tertiaryLabel">旧同步标记：{marker}</Text></Section>}
export function AccountScene({onAccountChanged}:{onAccountChanged?:(status:ReturnType<typeof getAccountStatus>)=>void}={}){const[account,setAccount]=useState(getAccountStatus());const update=(status:ReturnType<typeof getAccountStatus>)=>{setAccount(status);onAccountChanged?.(status)};return <List navigationTitle="账号与设置" navigationBarTitleDisplayMode="inline" listStyle="insetGroup" listSectionSpacing="compact"><AccountSection account={account} onAccountContextChanged={update}/><AccountOverviewEntry account={account}/><BuildMarker/></List>}

export function discoverGridMetrics(width:number){const available=Math.max(1,Number(width)||1),columns=available>=680?5:available>=460?3:2,spacing=12;return{columns,spacing,cardWidth:Math.max(1,Math.floor((available-spacing*(columns-1))/columns))}}
export function discoverCoverFrame(width=164){return {width:Math.max(1,Math.floor(width)),height:Math.min(178,Math.max(110,Math.round(width*1.12)))}}
function DiscoverWidthProbe({width,onWidth}:{width:number;onWidth:(width:number)=>void}){useEffect(()=>{if(width>0)onWidth(width)},[width]);return <VStack/>}
export function DiscoverCoverCard({item,width=164}:{item:GallerySummary;width?:number}){const imageFrame=discoverCoverFrame(width);return <VStack alignment="leading" spacing={5} frame={{width:imageFrame.width,alignment:"topLeading"}}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={imageFrame} cornerRadius={7}/>:<Image systemName="books.vertical" frame={imageFrame} foregroundStyle="secondaryLabel"/>}<Text font="subheadline" fontWeight="semibold" lineLimit={2} frame={{minHeight:44,alignment:"topLeading"}}>{workTitle(item.title)}</Text><Text font="caption" foregroundStyle="secondaryLabel" lineLimit={1}>{localizeCategory(item.category)}{item.pages>0?` · ${item.pages} 页`:""}</Text></VStack>}
export function DiscoverShowcase({items}:{items:GallerySummary[]}){const[selected,setSelected]=useState<GallerySummary|null>(null),[width,setWidth]=useState(0);return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=>{const grid=discoverGridMetrics(width|| (environment.horizontalSizeClass==="regular"?880:320));return <VStack alignment="leading" frame={{maxWidth:"infinity"}} background={<GeometryReader>{geometry=><DiscoverWidthProbe width={geometry.size.width} onWidth={setWidth}/>}</GeometryReader>} navigationDestination={listedGalleryDestination(environment.horizontalSizeClass,selected,setSelected)}><LazyVGrid columns={Array.from({length:grid.columns},()=>({size:{type:"flexible" as const},spacing:grid.spacing}))} alignment="leading" spacing={12}>{items.map(item=><Button key={galleryIdentity(item)} buttonStyle="plain" action={()=>openListedGallery(environment.horizontalSizeClass,item,setSelected)}><DiscoverCoverCard item={item} width={grid.cardWidth}/></Button>)}</LazyVGrid></VStack>}}</EnvironmentValuesReader>}
export function ContinueReadingCard({item,page}:{item:GallerySummary;page:number|null}){return <HStack spacing={8} padding={8} background="secondarySystemGroupedBackground" clipShape={{type:"rect",cornerRadius:12}}>{item.thumb?<CachedThumbnail url={item.thumb} stage="home-thumbnail" frame={{width:48,height:67}} cornerRadius={6}/>:<Image systemName="books.vertical" frame={{width:48,height:67}} foregroundStyle="secondaryLabel"/>}<VStack alignment="leading" spacing={4} frame={{maxWidth:"infinity"}}><Text font="subheadline" fontWeight="semibold" lineLimit={2}>{workTitle(item.title)}</Text>{page!=null&&item.pages>0?<ProgressView value={Math.max(0,Math.min(1,page/item.pages))} progressViewStyle="linear"/>:null}<Text font="caption" foregroundStyle="secondaryLabel" lineLimit={1}>{page!=null?`${page} / ${item.pages>0?item.pages:"—"} 页`:"尚未记录阅读页码"}</Text></VStack></HStack>}
function ContinueReadingStrip(){const[records,setRecords]=useState<Awaited<ReturnType<typeof loadHistory>>>([]),[selected,setSelected]=useState<GallerySummary|null>(null);useEffect(()=>{let cancelled=false,revision=0;const unsubscribe=subscribeHistory(value=>{revision++;if(!cancelled)setRecords(value)});const initialRevision=revision;void loadHistory().then(value=>{if(!cancelled&&revision===initialRevision)setRecords(value)}).catch(()=>{});return()=>{cancelled=true;unsubscribe()}},[]);if(!records.length)return <VStack/>;return <EnvironmentValuesReader keys={["horizontalSizeClass"]}>{environment=><VStack alignment="leading" spacing={6} frame={{maxWidth:"infinity"}} navigationDestination={listedGalleryDestination(environment.horizontalSizeClass,selected,setSelected)}><ShelfHeader title="继续阅读" action={<NavigationLink destination={<HistoryScene/>}><Text font="subheadline">查看全部</Text></NavigationLink>}/><ScrollView axes="horizontal"><HStack spacing={10}>{records.slice(0,8).map(record=>{const item=historySummary(record);return <Button key={`${record.gid}:${record.token}`} buttonStyle="plain" action={()=>openListedGallery(environment.horizontalSizeClass,item,setSelected)} frame={{width:260}}><ContinueReadingCard item={item} page={record.lastPageIndex!=null?record.lastPageIndex+1:null}/></Button>})}</HStack></ScrollView></VStack>}</EnvironmentValuesReader>}

export type DiscoverFeed = "latest" | "popular"
export function discoverFeedUrl(base:string,feed:DiscoverFeed){return buildGallerySearchUrl(base,feed==="popular"?createPopularSearchState():createHomeSearchState())}
export function mergeDiscoverGalleries(current:GallerySummary[],incoming:GallerySummary[]){const seen=new Set(current.map(galleryIdentity));return [...current,...incoming.filter(item=>{const key=galleryIdentity(item);if(seen.has(key))return false;seen.add(key);return true})]}
export function discoverNextCursor(requested:string,next:string){return next&&next!==requested?next:""}

function RecentDiscoverShelf({refresh}:{refresh:number}){const[items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("");useEffect(()=>{const controller=new AbortController();let cancelled=false;setLoading(true);setError("");void searchGalleries("",discoverFeedUrl(getBaseUrl(),"latest"),controller.signal).then(page=>{if(!cancelled)setItems(mergeDiscoverGalleries([],page.items).slice(0,5))}).catch(caught=>{if(!cancelled&&!controller.signal.aborted)setError(caught instanceof Error?caught.message:"最新画廊加载失败。")}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true;controller.abort()}},[refresh]);return <VStack alignment="leading" spacing={8} frame={{maxWidth:"infinity"}}><ShelfHeader title="最近更新" action={<NavigationLink destination={<ResultsView initial={createHomeSearchState()}/>}><Text font="subheadline">查看全部</Text></NavigationLink>}/>{loading&&!items.length?<ProgressView title="加载最近更新…"/>:null}{error?<ErrorText message={error}/>:null}<DiscoverShowcase items={items}/></VStack>}
export function HomeScene() {
  const dismiss=Navigation.useDismiss()
  const [feed,setFeed]=useState<DiscoverFeed>("popular"),feedRef=useRef<DiscoverFeed>("popular")
  const [items,setItems]=useState<GallerySummary[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState("")
  const [nextHomeUrl,setNextHomeUrl]=useState(""),[loadingMore,setLoadingMore]=useState(false),[moreError,setMoreError]=useState("")
  const requestEpoch=useRef(0),requestController=useRef<AbortController|null>(null),moreBusy=useRef(false),visited=useRef(new Set<string>())
  const nearBottom=useRef(false),scrollArmed=useRef(false),dragStarted=useRef(false)
  const [recentRefresh,setRecentRefresh]=useState(0)
  const [browse,setBrowse]=useState<{kind:"image"|"discovery"|"category"|"recommend"|"bookmarks";category?:GalleryCategoryKey}|null>(null)
  const loadHome=async(nextFeed:DiscoverFeed=feedRef.current,clear=false)=>{
    requestController.current?.abort();const controller=new AbortController();requestController.current=controller
    const epoch=++requestEpoch.current;feedRef.current=nextFeed;setFeed(nextFeed);moreBusy.current=false;scrollArmed.current=false;nearBottom.current=false
    visited.current=new Set();setNextHomeUrl("");setMoreError("");setLoadingMore(false);if(clear)setItems([]);setLoading(true);setError("")
    const current=()=>epoch===requestEpoch.current&&!controller.signal.aborted
    try{const url=discoverFeedUrl(getBaseUrl(),nextFeed),page=await searchGalleries("",url,controller.signal);if(current()){visited.current.add(url);setItems(mergeDiscoverGalleries([],page.items));setNextHomeUrl(discoverNextCursor(url,page.nextHref||""))}}
    catch(caught){if(current())setError(caught instanceof Error?caught.message:"画廊加载失败，请重试。")}
    finally{if(current())setLoading(false)}
  }
  const loadMoreHome=async()=>{
    if(moreBusy.current||loading||!nextHomeUrl)return
    moreBusy.current=true;scrollArmed.current=false;const epoch=requestEpoch.current,url=routeUrlForSite(nextHomeUrl),controller=new AbortController();requestController.current=controller
    const current=()=>epoch===requestEpoch.current&&!controller.signal.aborted
    setLoadingMore(true);setMoreError("")
    try{const page=await searchGalleries("",url,controller.signal);if(!current())return;visited.current.add(url);setItems(items=>mergeDiscoverGalleries(items,page.items));const next=discoverNextCursor(url,page.nextHref||"");setNextHomeUrl(visited.current.has(next)?"":next)}
    catch(caught){if(current())setMoreError(caught instanceof Error?caught.message:"加载下一页失败，请重试。")}
    finally{if(current()){moreBusy.current=false;setLoadingMore(false)}}
  }
  const requestMore=()=>{if(nearBottom.current&&scrollArmed.current&&!moreError)void loadMoreHome()}
  useEffect(()=>{void loadHome();return()=>{requestEpoch.current++;requestController.current?.abort()}},[])
  return <ScrollView navigationTitle="发现" navigationBarTitleDisplayMode="large" refreshable={()=>{setRecentRefresh(value=>value+1);return loadHome()}} background={<PageBackground/>}
    toolbar={{cancellationAction:<Button title="关闭" action={dismiss}/>}}
    onScrollTargetVisibilityChange={{idType:"string",threshold:0.01,onChanged:ids=>{nearBottom.current=ids.some(id=>id==="discover-load-boundary");requestMore()}}}
    simultaneousGesture={DragGesture({minDistance:12}).onChanged((value:any)=>{if(dragStarted.current)return;const dx=Number(value.translation?.width||0),dy=Number(value.translation?.height||0);if(dy>=-12||Math.abs(dy)<=Math.abs(dx))return;dragStarted.current=true;scrollArmed.current=true;requestMore()}).onEnded(()=>{dragStarted.current=false})}
    navigationDestination={{isPresented:Boolean(browse),onChanged:shown=>{if(!shown)setBrowse(null)},content:browse?.kind==="image"?<ImageSearchScene/>:browse?.kind==="recommend"?<AIRecommendationFlow/>:browse?.kind==="bookmarks"?<QuickSearchScene/>:browse?.kind==="discovery"?<DiscoveryScene initialKind="top"/>:browse?.kind==="category"&&browse.category?<ResultsView initial={createHomeSearchState("",browse.category,"none")}/>:<VStack/>}}>
    <VStack scrollTargetLayout alignment="leading" spacing={10} padding={{horizontal:16,vertical:8}} frame={{maxWidth:"infinity",alignment:"leading"}}>
      <Text font="caption" foregroundStyle="secondaryLabel">{getAccountStatus().site==="ex"?"ExHentai":"E-Hentai"} · 搜索、分类与发现</Text>
      <SearchComposer initial={createHomeSearchState()} compact/>
      <HStack spacing={4}><ScrollView axes="horizontal"><HStack spacing={16}><Button title="推荐" buttonStyle="plain" action={()=>setBrowse({kind:"recommend"})}/><Button buttonStyle="plain" action={()=>{if(feedRef.current!=="latest")void loadHome("latest",true)}}><Text fontWeight={feed==="latest"?"semibold":"regular"} foregroundStyle={feed==="latest"?"systemBlue":"secondaryLabel"} padding={{vertical:10}}>最新</Text></Button><Button buttonStyle="plain" action={()=>{if(feedRef.current!=="popular")void loadHome("popular",true)}}><Text fontWeight={feed==="popular"?"semibold":"regular"} foregroundStyle={feed==="popular"?"systemBlue":"secondaryLabel"} padding={{vertical:10}}>热门</Text></Button><Button title="排行榜" buttonStyle="plain" action={()=>setBrowse({kind:"discovery"})}/></HStack></ScrollView><Button title="搜索书签" systemImage="bookmark" labelStyle="iconOnly" buttonStyle="plain" frame={{minWidth:44,minHeight:44}} action={()=>setBrowse({kind:"bookmarks"})}/></HStack>

      {loading?<HStack spacing={8}><ProgressView progressViewStyle="circular"/><Text font="caption" foregroundStyle="secondaryLabel">正在加载{feed==="popular"?"热门":"最新"}画廊…</Text></HStack>:null}
      {error?<VStack alignment="leading" spacing={8}><ErrorText message={error}/><Button title="重试加载" buttonStyle="bordered" action={()=>void loadHome()}/></VStack>:null}
      {!loading&&!error&&!items.length?<EmptyState message="暂时没有可显示的画廊，可刷新或切换最新／热门。"/>:null}
      <ShelfHeader title={feed==="popular"?"热门发现":"最近更新"} /><DiscoverShowcase items={items.slice(0,5)}/>
      <ContinueReadingStrip/>
      {feed==="popular"?<RecentDiscoverShelf refresh={recentRefresh}/>:null}
      <ShelfHeader title={feed==="popular"?"更多热门":"更多最新"}/>
      <ScrollView axes="horizontal"><HStack spacing={8}>{GALLERY_CATEGORIES.map(item=><Button key={item.key} buttonStyle="plain" action={()=>setBrowse({kind:"category",category:item.key})}><Text padding={{horizontal:12,vertical:8}} background="secondarySystemBackground" clipShape={{type:"capsule",style:"continuous"}}>{item.shortLabel}</Text></Button>)}</HStack></ScrollView>
      <DiscoverShowcase items={items.slice(5)}/>
      {nextHomeUrl?<VStack key="discover-load-boundary" spacing={8} frame={{maxWidth:"infinity",minHeight:80}}>{loadingMore?<ProgressView title="加载更多画廊…" progressViewStyle="circular"/>:<><Text font="caption" foregroundStyle="secondaryLabel">继续上推浏览更多画廊</Text>{moreError?<ErrorText message={moreError}/>:null}<Button title={moreError?"重试加载更多":"加载更多"} buttonStyle="bordered" action={()=>void loadMoreHome()}/></>}</VStack>:null}
      <HStack spacing={12}><Button title="图片搜索" systemImage="photo.on.rectangle" action={()=>setBrowse({kind:"image"})}/><Button title="新闻" systemImage="newspaper" action={()=>void openExternalDestination("news").catch(caught=>setError(String(caught)))}/><Button title="论坛" systemImage="bubble.left.and.bubble.right" action={()=>void openExternalDestination("forums").catch(caught=>setError(String(caught)))}/></HStack>
    </VStack>
  </ScrollView>
}

